using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalNatural3DPines {
const string D="Assets/Scenes/Oasis/CoastalTerrain";static CoastalNatural3DPines(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalNatural3DPines.request"))return;try{File.Delete("CoastalNatural3DPines.request");}catch(IOException){return;}Run();}
class Geo{public List<Vector3> p=new List<Vector3>();public List<Color> c=new List<Color>();public List<Vector4> w=new List<Vector4>();public List<int> ids=new List<int>();public Vector3 anchor;public float height;
public void Tri(Vector3 a,Vector3 b,Vector3 d,Color color){int n=p.Count;foreach(var v in new[]{a,b,d}){p.Add(v);c.Add(color);w.Add(new Vector4(Mathf.Clamp01((v.y-anchor.y)/height),anchor.x,anchor.z,0));}ids.AddRange(new[]{n,n+1,n+2});}
public void Limb(Vector3 a,Vector3 b,float r0,float r1,int sides,Color color){var axis=(b-a).normalized;var right=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var forward=Vector3.Cross(axis,right);for(int k=0;k<sides;k++){float q=k*Mathf.PI*2/sides,s=(k+1)*Mathf.PI*2/sides;var v=right*Mathf.Cos(q)+forward*Mathf.Sin(q);var u=right*Mathf.Cos(s)+forward*Mathf.Sin(s);Tri(a+v*r0,b+v*r1,a+u*r0,color);Tri(a+u*r0,b+v*r1,b+u*r1,color);}}
public void Cluster(Vector3 center,Vector3 scale,float angle,Color color){var rot=Quaternion.Euler(0,angle,0);var lower=new Vector3[6];var upper=new Vector3[6];for(int k=0;k<6;k++){float a=k*Mathf.PI/3;float wobble=.83f+.17f*Mathf.Sin(k*2.73f+angle);lower[k]=center+rot*new Vector3(Mathf.Cos(a)*scale.x*wobble,-scale.y*.36f+Mathf.Sin(k*3.2f)*scale.y*.15f,Mathf.Sin(a)*scale.z*wobble);upper[k]=center+rot*new Vector3(Mathf.Cos(a+.13f)*scale.x*.78f*wobble,scale.y*.42f+Mathf.Cos(k*2.1f)*scale.y*.12f,Mathf.Sin(a+.13f)*scale.z*.78f*wobble);}var top=center+rot*new Vector3(scale.x*.17f,scale.y,0);var bottom=center-Vector3.up*scale.y*.72f;for(int k=0;k<6;k++){int n=(k+1)%6;Tri(lower[k],upper[k],lower[n],color);Tri(lower[n],upper[k],upper[n],color);Tri(upper[k],top,upper[n],color*1.06f);Tri(lower[n],bottom,lower[k],color*.8f);}}public void Write(Mesh mesh){mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(p);mesh.SetColors(c);mesh.SetUVs(1,w);mesh.SetUVs(0,p.Select(v=>Vector2.zero).ToList());mesh.SetTriangles(ids,0);mesh.RecalculateNormals();var normals=mesh.normals;var sums=new Dictionary<Vector3Int,Vector3>();for(int i=0;i<p.Count;i++){var key=new Vector3Int(Mathf.RoundToInt(p[i].x*1000),Mathf.RoundToInt(p[i].y*1000),Mathf.RoundToInt(p[i].z*1000));if(!sums.ContainsKey(key))sums[key]=Vector3.zero;sums[key]+=normals[i];}for(int i=0;i<p.Count;i++){var key=new Vector3Int(Mathf.RoundToInt(p[i].x*1000),Mathf.RoundToInt(p[i].y*1000),Mathf.RoundToInt(p[i].z*1000));normals[i]=Vector3.Lerp(normals[i],sums[key].normalized,.85f).normalized;}mesh.normals=normals;mesh.RecalculateBounds();var b=mesh.bounds;b.Expand(.6f);mesh.bounds=b;mesh.name="Natural layered 3D forest pine v2";EditorUtility.SetDirty(mesh);}}
static int trees,triangles;static void Build(Mesh mesh,bool far){if(mesh.name=="Natural layered 3D forest pine v2")return;var wind=new List<Vector4>();mesh.GetUVs(1,wind);var points=mesh.vertices;var groups=new Dictionary<Vector2,List<int>>();for(int i=0;i<points.Length;i++){var key=new Vector2(wind[i].y,wind[i].z);if(!groups.ContainsKey(key))groups[key]=new List<int>();groups[key].Add(i);}var geo=new Geo();foreach(var g in groups){float min=g.Value.Min(i=>points[i].y),max=g.Value.Max(i=>points[i].y);float h=max-min;geo.anchor=new Vector3(g.Key.x,min,g.Key.y);geo.height=h;var rng=new System.Random(Mathf.RoundToInt(g.Key.x*137+g.Key.y*271));Func<float> random=()=> (float)rng.NextDouble();Color bark=new Color(.23f,.16f,.095f,1);geo.Limb(geo.anchor,geo.anchor+Vector3.up*h*.98f,h*.014f,h*.0015f,far?4:6,bark);
int levels=far?5:8,branches=far?3:5;for(int level=0;level<levels;level++){float t=level/(float)(levels-1);float y=h*(.22f+.72f*t)+(random()-.5f)*h*.045f;float width=h*(.165f*(1-t)+.025f)*(.72f+random()*.42f);float phase=random()*360;for(int j=0;j<branches;j++){float a=(phase+j*360f/branches+(random()-.5f)*28)*Mathf.Deg2Rad;var direction=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var start=geo.anchor+Vector3.up*(y+(random()-.5f)*h*.03f);var end=start+direction*width+Vector3.up*h*(.015f-random()*.065f);if(!far)geo.Limb(start,end,h*.003f*(1-t*.6f),h*.0007f,4,bark);var center=Vector3.Lerp(start,end,.68f);var color=new Color(.035f+random()*.025f,.105f+random()*.055f,.042f+random()*.022f,1);geo.Cluster(center,new Vector3(width*.67f,h*(.052f+random()*.02f),width*.40f),-a*Mathf.Rad2Deg,color);if(!far&&level<6)geo.Cluster(end,new Vector3(width*.37f,h*.045f,width*.29f),-a*Mathf.Rad2Deg+20,new Color(.065f,.16f,.052f,1));}}geo.Cluster(geo.anchor+Vector3.up*h*.94f,new Vector3(h*.035f,h*.06f,h*.035f),0,new Color(.055f,.14f,.048f,1));trees++;}triangles+=geo.ids.Count/3;geo.Write(mesh);}
static void Run(){try{string path=D+"/Details/Shared 3D Forest Pine.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);var shader=AssetDatabase.LoadAssetAtPath<Shader>(D+"/Details/Mobile3DForestPine.shader");if(!mat){mat=new Material(shader);AssetDatabase.CreateAsset(mat,path);}mat.shader=shader;mat.SetColor("_Tint",Color.white);mat.SetFloat("_WindStrength",.18f);mat.SetFloat("_WindSpeed",.95f);mat.SetFloat("_PreviewTime",-1);mat.enableInstancing=true;EditorUtility.SetDirty(mat);var seen=new HashSet<Mesh>();int prefabs=0;foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{D+"/Prefabs"})){string file=AssetDatabase.GUIDToAssetPath(guid);if(!Path.GetFileName(file).StartsWith("Pine_")&&!Path.GetFileName(file).StartsWith("Natural Pine"))continue;var prefab=PrefabUtility.LoadPrefabContents(file);var wood=prefab.transform.Find("Forest trunks and branches");if(wood)UnityEngine.Object.DestroyImmediate(wood.gameObject);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){if(seen.Add(f.sharedMesh))Build(f.sharedMesh,f.name=="Distant");f.GetComponent<MeshRenderer>().sharedMaterial=mat;}var lod=prefab.GetComponent<LODGroup>();var levels=lod.GetLODs();foreach(var level in levels){}for(int i=0;i<levels.Length;i++)levels[i].renderers=levels[i].renderers.Where(r=>r).ToArray();lod.SetLODs(levels);lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,file);PrefabUtility.UnloadPrefabContents(prefab);prefabs++;}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Improved-Natural-3D-Pines"});File.WriteAllText("FinalEnvironmentRoadReview/Improved3DPineReport.txt","SUCCESS prefabs="+prefabs+" meshes="+seen.Count+" tree LOD representations="+trees+" total triangles="+triangles+"; solid 3D trunks, branches and asymmetric needle clusters, zero pine billboard cards; GPU wind and spatial batching; shader errors="+ShaderUtil.GetShaderMessages(shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/Improved3DPineReport.txt","FAILED "+e);Debug.LogException(e);}}
}
